function x({registerIndicator:u,sma:p,highest:d,lowest:f,change:N,nulls:g}){u({id:"oa-trama",name:"TRAMA: Trend Regularity Adaptive Moving Average",category:"Trends IIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:14,min:1,max:5e3,step:1}],plots:[{key:"trama",type:"line",title:"TRAMA",style:{color:"#ffeb3b",lineWidth:2}}],calc(o,b){const r=Math.max(1,Math.floor(Number(b.period)||14)),s=o.length,y=o.map(e=>e.high),F=o.map(e=>e.low),M=o.map(e=>e.close),A=N(d(y,r)),v=N(f(F,r)),h=new Array(s).fill(0);for(let e=0;e<s;e++){const i=A[e],a=v[e],n=Number.isFinite(i)?Math.max(Math.sign(i),0):NaN,t=Number.isFinite(a)?Math.max(Math.sign(a*-1),0):NaN,m=Number.isFinite(n)&&n!==0||Number.isFinite(t)&&t!==0;h[e]=m?1:0}const l=p(h,r),c=new Array(s).fill(NaN);for(let e=0;e<s;e++){const i=e>0?c[e-1]:NaN,a=Number.isFinite(i)?i:0,n=M[e];let t=NaN;if(Number.isFinite(l[e])&&Number.isFinite(n)){const m=l[e]*l[e];t=a+m*(n-a)}Number.isFinite(i)||(t=n),c[e]=Number.isFinite(t)?t:NaN}return{trama:g(c)}}})}export{x as default};
